(function () {
  'use strict';

  const PROJECTS = {
    p1: {
      year: '2025', url: 'la-vaca-web.vercel.app', full: ['lavaca-fullpage-v5.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'La Vaca — Bar de barrio', role: 'LCS · Diseño & Desarrollo Web', client: 'La Vaca · Grand Bourg, Salta',
        problem: 'La Vaca es una sanguchería de barrio en Álvarez Thomas 714, Grand Bourg, que abre solo de noche: de 20:30 a 00:30 entre semana y hasta la 01:30 los fines de semana. Su público llegaba por Instagram y por las apps de delivery, sin un lugar propio donde ver qué se pide, hasta qué hora está abierto ni por dónde encargar. El riesgo era el opuesto al habitual: una web demasiado prolija hubiera traicionado a un local que se define por no tener pretensiones.',
        goal: 'Darle una web con el tono real del local —barrial, nocturno, sin pose— que resuelva las tres preguntas que importan a la una de la mañana: qué hay, hasta qué hora y cómo lo pido.',
        steps: [['01','Descubrir','Cómo y cuándo pide el cliente: apps, WhatsApp o retiro en local'],['02','Definir','Prioridad: menú, horarios de cada día y canales de pedido'],['03','Diseñar','Dirección nocturna en negro y rojo, tipografía condensada de cartel'],['04','Entregar','One-page responsive con click-to-call y mapa']],
        result: 'Sitio en vivo con el manifiesto del local en el hero ("no somos un restaurante, somos el lugar donde terminás la noche"), los seis productos con su foto y su descripción —lomito, burga, papas, milanga, bondiola y juliana—, la tabla de horarios día por día, los tres canales de pedido (Rappi, PedidosYa y retiro en local) y el bloque de contacto con WhatsApp, Instagram, Facebook, mail y mapa.',
        learn: 'El primer proyecto del estudio, y el que fijó una regla: el diseño tiene que sonar como habla el cliente. Acá el copy manda sobre la estética, y una web más "elegante" hubiera vendido menos.' },
      en: { cat: 'Web Design + UX/UI', title: 'La Vaca — Neighbourhood bar', role: 'LCS · Web Design & Development', client: 'La Vaca · Grand Bourg, Salta',
        problem: 'La Vaca is a neighbourhood sandwich bar at Álvarez Thomas 714, Grand Bourg, open nights only: 8:30pm to 12:30am on weekdays and until 1:30am on weekends. Its customers arrived via Instagram and delivery apps, with no place of their own to see what is on offer, how late it stays open or where to order. The risk was the opposite of the usual one: an over-polished site would have betrayed a place that defines itself by having no pretensions.',
        goal: 'Give it a site in the venue\'s real voice — local, nocturnal, no posturing — answering the three questions that matter at 1am: what is there, until when, and how do I order.',
        steps: [['01','Discover','How and when customers order: apps, WhatsApp or pickup'],['02','Define','Priority: menu, day-by-day hours and ordering channels'],['03','Design','Nocturnal black-and-red direction, condensed signage type'],['04','Deliver','Responsive one-pager with click-to-call and map']],
        result: 'Live site leading with the venue\'s own manifesto ("we are not a restaurant, we are where your night ends"), the six products with photo and description — lomito, burger, fries, milanesa, pulled pork and the veggie one — a day-by-day hours table, the three ordering channels (Rappi, PedidosYa and pickup) and a contact block with WhatsApp, Instagram, Facebook, email and map.',
        learn: 'The studio\'s first project, and the one that set a rule: design has to sound the way the client speaks. Here the copy leads and the aesthetics follow — a more "elegant" site would have sold less.' }
    },
    p2: {
      year: '2025', url: 'brunetti-jade.vercel.app', full: ['brunetti-fullpage-v4.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web', title: 'Frigorífico Brunetti', role: 'LCS · Diseño & Desarrollo Web', client: 'Establecimiento Frigorífico Brunetti · Salta',
        problem: 'Brunetti es una empresa familiar salteña que faena, desposta y distribuye carne vacuna desde 1981, cuando compró su predio en una licitación pública de la provincia. Opera como Compañía Industrializadora Argentina de Carnes S.A., procesa unas treinta mil cabezas por año y da trabajo a cerca de ciento cincuenta familias, pero no tenía sitio propio: el comprador mayorista que quería precio o coordinar un reparto no encontraba ni el teléfono, y la trazabilidad —su mayor argumento frente a la competencia— no estaba contada en ningún lado.',
        goal: 'Construir la presencia institucional que faltaba: dejar la trayectoria y la trazabilidad a la vista, y llevar tanto al mayorista como al público a la llamada, que es donde el negocio efectivamente cierra.',
        steps: [['01','Descubrir','Los dos públicos del frigorífico: mayorista y mostrador'],['02','Definir','Ejes: 1981, treinta mil cabezas, trazabilidad por lote y dos puntos de venta'],['03','Diseñar','Dirección sobria de campo, tipografía con serifa y fotografía propia del establecimiento'],['04','Entregar','Una sola página responsive, con teléfono directo y mapa por sucursal']],
        result: 'Sitio en vivo de una sola página que abre sobre el campo con “Tradición ganadera” y baja en seis movimientos. El origen, con el predio, la planta y el reparto explicados uno por uno. El proceso en cuatro etapas —hacienda, faena bajo inspección del SENASA, frío y reparto— apoyado en el dato que sostiene todo lo demás: cada media res sale de la cámara con su etiqueta de lote. Cinco cortes en carrusel, cada uno con su nombre de exportación, su peso habitual, su nivel de marmoleo y la cocción que le sienta. Una cinta que repite los seis datos duros del establecimiento. La galería del predio, la planta y su gente, con la aclaración de que ninguna foto viene de un banco de imágenes. Y el cierre en las dos direcciones de Salta Capital, cada una con su teléfono directo, su horario y su mapa: el mayorista del barrio Solís Pizarro y el local de Avenida San Martín.',
        learn: 'En B2B alimentario la confianza no se declara, se documenta. Contar que cada media res lleva un número de lote que permite reconstruir de qué tropa vino y qué día se faenó vale más que cualquier adjetivo sobre la calidad. Por eso el sitio no lleva formulario: el precio de mayorista y la coordinación del reparto se cierran hablando, así que cada camino termina en un teléfono que se marca de un toque.' },
      en: { cat: 'Web Design', title: 'Frigorífico Brunetti', role: 'LCS · Web Design & Development', client: 'Establecimiento Frigorífico Brunetti · Salta',
        problem: 'Brunetti is a family-run Salta company that has slaughtered, butchered and distributed beef since 1981, when it bought its site in a provincial public tender. Trading as Compañía Industrializadora Argentina de Carnes S.A., it processes some thirty thousand head a year and supports around one hundred and fifty families, yet had no site of its own: wholesale buyers looking for prices or delivery scheduling could not even find the phone number, and traceability — its strongest argument against competitors — was documented nowhere.',
        goal: 'Build the missing corporate presence: put the track record and traceability in plain sight, and lead both wholesalers and walk-in customers to the phone call, where the business actually closes.',
        steps: [['01','Discover','The plant\'s two audiences: wholesale and counter'],['02','Define','Pillars: 1981, thirty thousand head, batch traceability and two shops'],['03','Design','Sober rural direction, serif type and the establishment\'s own photography'],['04','Deliver','A single responsive page, with a direct line and map per branch']],
        result: 'A live one-page site that opens over the pasture with “Tradición ganadera” and unfolds in six movements. The origin, with the grounds, the plant and distribution each explained in turn. The four-stage process — livestock, slaughter under SENASA inspection, chilling and delivery — resting on the fact that carries everything else: every half-carcass leaves the chiller with its batch label. Five cuts in a carousel, each with its export name, usual weight, marbling level and the cooking that suits it. A ticker repeating the establishment\'s six hard facts. The gallery of the grounds, the plant and its people, noting that not one photograph comes from a stock library. And the close on both Salta Capital addresses, each with its direct line, opening hours and map: the wholesale plant in Barrio Solís Pizarro and the Avenida San Martín shop.',
        learn: 'In B2B food, trust is not declared, it is documented. Explaining that every half-carcass carries a batch number that traces which herd it came from and the day it was processed is worth more than any adjective about quality. That is why the site carries no form: wholesale pricing and delivery scheduling get settled by talking, so every path ends on a phone number one tap away.' }
    },
    p3: {
      year: '2026', url: 'dona-salta-landing.vercel.app', full: ['donasalta-fullpage-v3.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Doña Salta', role: 'LCS · Diseño & Desarrollo Web', client: 'Doña Salta · Córdoba 46, Salta capital',
        problem: 'Doña Salta es un bodegón de generaciones en Córdoba 46, frente a la Basílica de San Francisco: 4,5 sobre 5 con más de 25.000 reseñas en Google, puesto 11 de 377 en TripAdvisor y Travelers\' Choice 2025. Toda esa reputación vivía en plataformas de terceros, y el turista que buscaba la carta, los precios o el horario terminaba en un portal ajeno. El local además no toma reservas ni tiene delivery, así que las mismas preguntas entraban por teléfono todos los días.',
        goal: 'Convertir la reputación prestada en un sitio propio que conteste de antemano lo que se pregunta por teléfono —precio, horario, cómo llegar, si hace falta reservar— y deje el encargo a un solo toque en el número del local.',
        steps: [['01','Descubrir','Las preguntas reales que entran por teléfono y qué busca el turista'],['02','Definir','Una página por intención: empanadas, carta, el bodegón y cómo llegar'],['03','Diseñar','Paleta cálida de adobe y papel, tipografía serif y foto propia del local en cada bloque'],['04','Entregar','Sitio multipágina responsive con click-to-call y mapa']],
        result: 'Sitio de siete páginas. El inicio abre con la fachada real y la prueba social en cuatro cifras verificables, sigue con el horno de barro y el repulgue, y cierra en Córdoba 46 con horarios y teléfono. Cada intención tiene su página: los cuatro rellenos explicados uno por uno —carne a cuchillo, charqui, queso y pollo, todos al mismo precio para que la docena se pida surtida, a $2.000 la unidad y $24.000 la docena—; la carta completa del salón en ocho secciones con precios reales, del locro a $25.000 a la cazuela de cabrito a $38.000 y los vinos salteños de altura; el bodegón por dentro (adobe, cañas de bambú, mozos de sombrero) aclarando que ninguna foto es de banco de imágenes; y una página de visita con siete preguntas frecuentes que responden lo que más se pregunta: si hace falta reservar, cuánto sale la docena, si hay delivery, si hay opciones sin carne y si se pueden llevar empanadas para el viaje de vuelta.',
        learn: 'Cuando un local no toma reservas ni tiene delivery, la web no está para vender online: está para ahorrar llamadas. Ordenar el contenido por la pregunta que se hace el comensal —y no por las secciones del negocio— fue lo que definió la arquitectura, y publicar los precios completos en vez de esconderlos detrás de un PDF es lo que hace que la página reemplace de verdad al llamado.' },
      en: { cat: 'Web Design + UX/UI', title: 'Doña Salta', role: 'LCS · Web Design & Development', client: 'Doña Salta · Córdoba 46, Salta',
        problem: 'Doña Salta is a generations-old bodegón at Córdoba 46, facing the San Francisco Basilica: 4.5 out of 5 across more than 25,000 Google reviews, ranked 11th of 377 on TripAdvisor and a 2025 Travelers\' Choice. All that reputation lived on third-party platforms, and visitors looking for the menu, prices or hours ended up on someone else\'s portal. The venue also takes no bookings and has no delivery, so the same questions came in by phone every day.',
        goal: 'Turn borrowed reputation into an owned site that answers upfront what people ask on the phone — price, hours, directions, whether booking is needed — and puts the order one tap away on the venue\'s number.',
        steps: [['01','Discover','The real questions arriving by phone and what visitors look for'],['02','Define','One page per intent: empanadas, menu, the bodegón and directions'],['03','Design','Warm adobe-and-paper palette, serif type and the venue\'s own photography throughout'],['04','Deliver','Responsive multi-page site with click-to-call and map']],
        result: 'A seven-page site. The homepage opens with the real façade and social proof in four verifiable figures, moves through the clay oven and the hand-crimped edge, and closes at Córdoba 46 with hours and phone. Every intent gets its own page: the four fillings explained one by one — knife-cut beef, charqui, cheese and chicken, all the same price so a dozen can be ordered mixed, at $2,000 each and $24,000 the dozen —; the full dining-room menu across eight sections with real prices, from locro at $25,000 to the kid-goat casserole at $38,000 and the high-altitude Salta wines; the bodegón from the inside (adobe, bamboo canes, waiters in Salta hats), stating plainly that no photograph is stock; and a visit page whose seven FAQs answer what is asked most: whether to book, what a dozen costs, whether there is delivery, whether there are meat-free options and whether empanadas can be taken on the trip home.',
        learn: 'When a venue takes no bookings and has no delivery, the site is not there to sell online: it is there to save phone calls. Organizing content around the diner\'s question — rather than the business\'s sections — is what defined the architecture, and publishing full prices instead of hiding them behind a PDF is what lets the page genuinely replace the call.' }
    },
    p4: {
      year: '2026', url: 'espacio-zur.vercel.app', full: ['zur-fullpage-v2.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Espacio Zur', role: 'LCS · Diseño & Desarrollo Web', client: 'Espacio Zur · Ganimedes y Marte, Barrio Casa del Sol, Salta',
        problem: 'Espacio Zur no es un gimnasio y no quería parecerlo. Su propuesta —movimiento consciente, seis disciplinas grupales y planes personalizados de recuperación— se confundía con la de cualquier gym de barrio en el momento en que alguien la buscaba online. A eso se sumaba que está en Ganimedes y Marte, en Barrio Casa del Sol, fuera del circuito céntrico: quien no lo conocía de boca en boca no tenía cómo saber qué se hace adentro ni si su caso —una lesión, una vuelta a la actividad— entraba ahí.',
        goal: 'Construir una identidad digital que separe a Zur del gimnasio tradicional, explique las seis prácticas y el trabajo de recuperación en sus propios términos, y lleve la consulta al WhatsApp, que es donde efectivamente se reserva la clase.',
        steps: [['01','Descubrir','Qué buscan quienes llegan por dolor, postura o vuelta a la actividad'],['02','Definir','Mensaje: "más que un gimnasio", cuerpo + mente + identidad'],['03','Diseñar','Sistema oscuro y editorial en negro y arena, secciones numeradas 01–04'],['04','Entregar','One-page responsive con FAQ, WhatsApp flotante, Instagram y mapa']],
        result: 'One-page en vivo dividida en cuatro secciones numeradas. Abre con el hero a pantalla completa —"donde tu cuerpo y tu mente se equilibran"— y sigue con el "más que un gimnasio", que define a Zur como propuesta de movimiento consciente sobre tres ejes: comunidad, el espacio e identidad. Las seis disciplinas grupales van una a una con su descripción —movimiento consciente, entrenamiento funcional, yoga & stretching, movilidad integral, respiración consciente y comunidad Zur—, y las clases personalizadas tienen su propio bloque con los seis componentes del plan: evaluación inicial, acompañamiento individual, movilidad y fortalecimiento progresivo, mejora postural, prevención de lesiones y seguimiento profesional. Cierra con la galería del lugar, el contacto en Ganimedes y Marte con mapa, teléfono directo e Instagram, y cinco preguntas frecuentes que sacan las dudas de entrada: si hace falta experiencia previa, qué incluye una clase personalizada, cómo se reserva, dónde queda y qué disciplinas hay. El botón de WhatsApp queda fijo en pantalla durante todo el scroll.',
        learn: 'Cuando la categoría está saturada, el diseño tiene que decir primero lo que la marca no es. Todo el sistema visual se construyó alrededor de esa distancia, y la FAQ terminó haciendo el trabajo más comercial de la página: contestar "no hace falta experiencia previa" antes de que la duda frene la consulta.' },
      en: { cat: 'Web Design + UX/UI', title: 'Espacio Zur', role: 'LCS · Web Design & Development', client: 'Espacio Zur · Ganimedes y Marte, Casa del Sol, Salta',
        problem: 'Espacio Zur is not a gym and did not want to look like one. Its offer — conscious movement, six group disciplines and personalized recovery plans — blended into any neighbourhood gym the moment someone searched for it online. It also sits at Ganimedes y Marte, in Barrio Casa del Sol, away from the central circuit: anyone who had not heard of it by word of mouth had no way of knowing what happens inside, or whether their case — an injury, a comeback — belonged there.',
        goal: 'Build a digital identity that separates Zur from the traditional gym, explains the six practices and the recovery work in its own terms, and drives the enquiry to WhatsApp, where classes are actually booked.',
        steps: [['01','Discover','What people arriving with pain, posture or a comeback are looking for'],['02','Define','Message: "more than a gym", body + mind + identity'],['03','Design','Dark editorial system in black and sand, numbered 01–04 sections'],['04','Deliver','Responsive one-pager with FAQ, floating WhatsApp, Instagram and map']],
        result: 'A live one-pager split into four numbered sections. It opens on a full-screen hero — "where your body and your mind find balance" — and moves into the "more than a gym" statement, defining Zur as a conscious-movement practice across three pillars: community, the space and identity. The six group disciplines are covered one by one with their descriptions — conscious movement, functional training, yoga & stretching, integral mobility, conscious breathing and Comunidad Zur — and the personalized sessions get their own block with the six parts of the plan: initial assessment, one-to-one guidance, progressive mobility and strengthening, postural improvement, injury prevention and professional follow-up. It closes with the venue gallery, the contact block at Ganimedes y Marte with map, direct phone and Instagram, and five FAQs clearing the entry doubts: whether previous experience is needed, what a personalized session includes, how to book, where it is and which disciplines are offered. The WhatsApp button stays pinned on screen throughout the scroll.',
        learn: 'When a category is crowded, design has to say first what the brand is not. The whole visual system was built around that distance, and the FAQ ended up doing the most commercial work on the page: answering "no previous experience needed" before the doubt stops the enquiry.' }
    },
    p5: {
      year: '2026', url: 'jockeyclubsalta.vercel.app', full: ['jockey-fullpage-v2.webp', 'jockey-fullpage2-v2.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Jockey Club Salta', role: 'LCS · Diseño & Desarrollo Web', client: 'Jockey Club de Salta · Sede Limache y anexo Las Costas',
        problem: 'El Jockey Club de Salta —el Rojo y Blanco desde 1965, campeón del WERE M15 en 2026, con seis deportes, dos sedes y cerca de 1.800 socios activos— necesitaba una web que no fuera un tablón de anuncios institucional. El desafío era transmitirle a alguien de afuera algo que los socios solo saben desde adentro: qué es ser del Jockey. Y hacerlo sin perder la parte útil: horarios de práctica, calendario, posiciones y dónde queda cada cosa.',
        goal: 'Diseñar una home-manifiesto que haga sentir la pertenencia antes de informar, y recién después abrir las seis puertas del club: historia, camadas, espacios, vida social, disciplinas y experiencia sonora.',
        steps: [['01','Descubrir','Historia del club, camadas, rituales, giras y tercer tiempo'],['02','Definir','Home como manifiesto y seis secciones, no un índice de novedades'],['03','Diseñar','Scroll narrado en siete cuadros pinneados, sonido opcional y paleta rojo/blanco'],['04','Entregar','Prototipo de alta fidelidad de siete páginas']],
        result: 'Prototipo de siete páginas. La home es un manifiesto pinneado: siete cuadros a pantalla completa que se van cruzando con el scroll —"acá no se viene a mirar, se viene a pertenecer", "fuimos rayas, nos hicimos cuadros", "rojo y blanco desde 1965"— con capa de sonido opcional, y recién al final aparece la grilla de seis puertas. Detrás, cada puerta está desarrollada: la historia baja por el tiempo del turf de don Fonzo a la misa de Juan Pablo II del 87, con medio millón de personas en los campos del club, y al título M15 de 2026; las camadas son una constelación donde cada promoción es una estrella que se enciende con sus fotos, apodos y dónde está hoy cada uno; los espacios recorren la Cancha 1 con su ficha técnica, la tribuna Fonzo, la casa roja, el hockey, las nueve canchas de tenis, los dieciocho hoyos de golf y el anexo Las Costas; la vida social trae el calendario filtrable de partidos, fiestas, asados y giras más la galería del banderazo; las disciplinas abren las seis con horarios de práctica, próximos partidos y tablas de posiciones; y "Sentir el Rojo" cierra con un paisaje sonoro de cuatro actos.',
        learn: 'En una institución con historia, el mejor argumento de conversión no es la información: es el sentido de pertenencia. La arquitectura se ordenó para que la emoción venga primero y el dato después —pero el dato tiene que estar, porque el socio que entra a ver a qué hora entrena la M15 vuelve todas las semanas, y el que se emociona con el manifiesto entra una sola vez.' },
      en: { cat: 'Web Design + UX/UI', title: 'Jockey Club Salta', role: 'LCS · Web Design & Development', client: 'Jockey Club de Salta · Limache and Las Costas',
        problem: 'Jockey Club de Salta — the Red and White since 1965, 2026 WERE M15 champions, six sports, two grounds and around 1,800 active members — needed a site that was not an institutional noticeboard. The challenge was conveying to an outsider something only members know from the inside: what it means to belong to the Jockey. And doing it without losing the useful part: training times, fixtures, standings and where everything is.',
        goal: 'Design a manifesto homepage that makes belonging felt before it informs, and only then opens the club\'s six doors: history, cohorts, grounds, social life, sports and the sound experience.',
        steps: [['01','Discover','Club history, cohorts, rituals, tours and the third half'],['02','Define','Home as a manifesto plus six sections, not a news index'],['03','Design','Narrated scroll across seven pinned frames, optional sound, red/white palette'],['04','Deliver','Seven-page high-fidelity prototype']],
        result: 'A seven-page prototype. The homepage is a pinned manifesto: seven full-screen frames crossfading with the scroll — "you don\'t come here to watch, you come to belong", "we were stripes, we became quarters", "red and white since 1965" — with an optional sound layer, and only at the end does the six-door grid appear. Behind each door the section is fully built: history runs from don Fonzo and the turf to the 1987 mass of John Paul II, with half a million people on the club grounds, and on to the 2026 M15 title; the cohorts form a constellation where each year group is a star that lights up with photos, nicknames and where everyone is today; the grounds walk through Cancha 1 with its spec sheet, the Fonzo stand, the red clubhouse, hockey, the nine tennis courts, the eighteen golf holes and the Las Costas annex; social life brings a filterable calendar of matches, parties, asados and tours plus the banderazo gallery; the sports section opens all six with training times, upcoming fixtures and standings; and "Sentir el Rojo" closes with a four-act soundscape.',
        learn: 'In an institution with history, the strongest conversion argument is not information — it is belonging. The architecture was ordered so emotion comes first and data second, but the data has to be there: the member checking what time the M15 trains comes back every week, while the one moved by the manifesto comes once.' }
    },
    p6: {
      year: '2026', url: 'ipv-salta.vercel.app', full: ['ipv-fullpage-v2.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'IPV', role: 'LCS · Diseño & Desarrollo Web', client: 'Instituto Provincial de Vivienda · Salta',
        problem: 'El IPV concentra trámites de altísimo volumen y muy alta ansiedad: inscripción a vivienda, boletas, turnos, sorteos, cambios de titularidad, escrituración. Todo eso convivía sin jerarquía, y la persona que entra con una sola pregunta ("¿salí sorteada?", "¿dónde pago?") tenía que adivinar el camino. A eso se suma un problema propio del organismo: los falsos gestores que cobran por trámites que son gratuitos.',
        goal: 'Rediseñar la arquitectura de información alrededor de las tareas más buscadas, para que se resuelvan desde la primera pantalla sin navegar de más, y dejar la advertencia sobre falsos gestores donde no se pueda pasar por alto.',
        steps: [['01','Descubrir','Inventario de trámites y volumen real de consultas'],['02','Definir','Seis accesos directos y un buscador por encima de todo lo demás'],['03','Diseñar','Sistema institucional accesible, agrupado por intención'],['04','Entregar','Sitio multipágina responsive con programas, sorteos, pagos y sedes']],
        result: 'Sitio en vivo con siete secciones. La home abre con buscador de trámites y seis accesos directos sobre la foto de obra —inscribirme a vivienda, pagar o imprimir boleta, sacar turno web, ver requisitos, consultar estado de trámite y contrataciones vigentes—, sigue con las novedades, los programas y una grilla de trámites agrupados por intención en seis bloques: inscripción, pagos y boletas, escritura y titularidad, turnos y atención, documentos y validaciones, y alertas e información. Detrás, cada sección está desarrollada: los ocho programas federales y provinciales con su descripción y sus cupos —de Plan Mi Lote con más de 10.000 lotes a Casa Activa para mayores de 60—, los ocho canales de pago (online por Macro Click, Pago Mis Cuentas, sucursal, Pago Fácil, Rapipago, adherido a la boleta de EDESA, débito automático y aranceles), el calendario de sorteos con fecha, hora y cantidad de viviendas, y la página completa de falsos gestores con los cuatro consejos y los canales oficiales. Cierra con las cuatro sedes —Capital, Metán, Tartagal y Orán— cada una con dirección y teléfono.',
        learn: 'En un sitio público el éxito no se mide en tiempo de permanencia sino en lo contrario: cuánto tarda alguien en resolver e irse. La home se diseñó para vaciarse rápido, y por eso el buscador y los seis accesos van antes que cualquier mensaje institucional.' },
      en: { cat: 'Web Design + UX/UI', title: 'IPV', role: 'LCS · Web Design & Development', client: 'Provincial Housing Institute · Salta',
        problem: 'IPV concentrates high-volume, high-anxiety procedures: housing registration, bills, appointments, draws, title transfers, deeds. All of it coexisted without hierarchy, and someone arriving with a single question ("did my number come up?", "where do I pay?") had to guess the path. On top of that sits a problem specific to the institute: fake agents charging for procedures that are free.',
        goal: 'Redesign the information architecture around the most-sought tasks so they resolve from the first screen without extra navigation, and put the fake-agent warning where it cannot be missed.',
        steps: [['01','Discover','Inventory of procedures and real query volume'],['02','Define','Six shortcuts and a search box above everything else'],['03','Design','Accessible institutional system, grouped by intent'],['04','Deliver','Responsive multi-page site with programs, draws, payments and offices']],
        result: 'A live site with seven sections. The homepage opens with a procedure search box and six shortcuts over the construction photograph — register for housing, pay or print a bill, book an appointment, see requirements, check application status and current tenders — then moves through news, programs and a grid of procedures grouped by intent into six blocks: registration, payments and bills, deeds and title, appointments, documents and validations, and alerts. Behind it, every section is built out: the eight federal and provincial programs with their descriptions and quotas — from Plan Mi Lote with over 10,000 plots to Casa Activa for over-60s — the eight payment channels (online via Macro Click, Pago Mis Cuentas, bank branch, Pago Fácil, Rapipago, added to the EDESA electricity bill, direct debit and fees), the draw calendar with date, time and number of homes, and a full fake-agents page with four pieces of advice and the official channels. It closes with the four offices — Capital, Metán, Tartagal and Orán — each with address and phone.',
        learn: 'On a public site, success is not measured in time on page but the opposite: how fast someone resolves and leaves. The homepage was designed to empty out quickly, which is why the search box and the six shortcuts come before any institutional message.' }
    },
    p7: {
      year: '2026', url: 'odontologiaforlani.vercel.app', full: ['forlani-fullpage-v3.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Dra. Karina Forlani', role: 'LCS · Diseño & Desarrollo Web', client: 'Dra. Karina Forlani · Matrícula 50872 · Campana, Buenos Aires',
        problem: 'La Dra. Forlani lleva más de quince años haciendo ortodoncia estética en Campana y ya vio cambiar más de doscientas sonrisas, con una práctica de mínima invasión: cuidar lo propio y tocar apenas lo necesario. Nada de eso tenía dónde mostrarse. Quien buscaba alineadores invisibles en la zona encontraba cadenas y precios de góndola, sin poder ver quién iba a atenderlo ni resolver las dudas que de verdad frenan la decisión: cuánto dura, si duele, cuánto sale.',
        goal: 'Poner la confianza en el centro —la cara de quien atiende y resultados reales, no renders— y llevar la consulta directo al WhatsApp, sin formularios ni intermediarios.',
        steps: [['01','Descubrir','Las dudas que el paciente hace antes de empezar y las que no se anima a preguntar'],['02','Definir','Eje: mínima invasión, plan digital en 3D y trato directo con la profesional'],['03','Diseñar','Estética clínica cálida en verde y crema, con el antes y después como pieza central'],['04','Entregar','Sitio de una página, responsive, con WhatsApp presente en todo el scroll']],
        result: 'Sitio en vivo de una sola página. El centro es un comparador deslizable de antes y después sobre un caso real, publicado con permiso de la paciente y acompañado de su testimonio; los alineadores explicados sin tecnicismos —fundas transparentes que se cambian cada un par de semanas y se sacan para comer—, con la aclaración de que si el caso pide brackets también se trabajan; el proceso en cuatro pasos, del escaneo digital sin moldes al seguimiento hasta el alta; seis preguntas frecuentes que responden de frente lo que traba la consulta, incluidos los seis a dieciocho meses de duración típica y los controles cada cuatro a seis semanas; y un bloque de contacto con horarios, mapa y la matrícula 50872 a la vista.',
        learn: 'En salud, el antes y después hace el trabajo pesado, pero solo si va con la cara de quien atiende al lado: la foto de la doctora y el testimonio de la paciente convencen más que cualquier listado de tecnología. Y responder el precio con honestidad —«lo definimos después de ver tu caso», con planes— rinde más que esquivarlo.' },
      en: { cat: 'Web Design + UX/UI', title: 'Dra. Karina Forlani', role: 'LCS · Web Design & Development', client: 'Dr. Karina Forlani · Licence 50872 · Campana, Buenos Aires',
        problem: 'Dr. Forlani has spent over fifteen years doing aesthetic orthodontics in Campana and has watched more than two hundred smiles change, working to a minimally invasive principle: protect what is already there and touch only what is needed. None of it had anywhere to show. Anyone searching for invisible aligners nearby found chains and shelf prices, never the person who would actually treat them, and never an answer to what really stalls the decision: how long, does it hurt, what does it cost.',
        goal: 'Put trust at the centre — the face of the person treating you and real results, not renders — and take the enquiry straight to WhatsApp, with no forms and no middlemen.',
        steps: [['01','Discover','The questions patients ask before starting, and the ones they do not dare ask'],['02','Define','Core: minimal invasion, a 3D digital plan and direct care from the practitioner'],['03','Design','Warm clinical aesthetic in green and cream, with before/after as the centrepiece'],['04','Deliver','A responsive single-page site with WhatsApp present throughout the scroll']],
        result: 'A live single-page site. At its centre, a draggable before/after slider on a real case published with the patient\'s permission and carried by her own words; aligners explained without jargon — clear trays swapped every couple of weeks and taken out to eat — with the note that braces are fitted too when a case calls for them; the process in four steps, from the mould-free digital scan to follow-up until discharge; six FAQs answering head-on what holds an enquiry back, including the typical six to eighteen months and check-ups every four to six weeks; and a contact block with opening hours, a map and licence number 50872 in plain sight.',
        learn: 'In healthcare the before/after does the heavy lifting, but only with the practitioner\'s face beside it: the doctor\'s photo and the patient\'s own words convince more than any list of technology. And answering the price question honestly — "we work it out once I have seen your case", with payment plans — beats dodging it.' }
    },
    p8: {
      year: '2026', url: 'baltazar-aguiar.vercel.app', full: ['baltazar-fullpage-v2.webp'], tools: ['Figma', 'Next.js', 'React'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Baltazar Aguiar', role: 'LCS · Diseño & Desarrollo Web', client: 'Baltazar Aguiar · Marketing gastronómico',
        problem: 'Baltazar asesora a dueños de restaurantes y tiene una comunidad de casi treinta mil personas, pero toda su autoridad vivía en Instagram y TikTok. Sin un sitio propio, el seguidor que quería contratarlo no tenía dónde entender la oferta ni ver la prueba de que el sistema funciona.',
        goal: 'Transformar audiencia en clientes: una landing de venta que ordene diagnóstico, método, resultados y programa, y termine en una llamada agendada.',
        steps: [['01','Descubrir','Objeciones reales del dueño de restaurante antes de contratar'],['02','Definir','Estructura de venta: diagnóstico → método → prueba → oferta'],['03','Diseñar','Dirección editorial oscura, tipografía display y números grandes'],['04','Entregar','Desarrollo en Next.js, responsive y con CTA por WhatsApp']],
        result: 'Landing larga de conversión: diagnóstico en tres causas, método en cuatro etapas, bloque de resultados con cifras ($26M de facturación mensual partiendo de 15M, +20 negocios, ×2 en promedio), cuatro casos cortos, el programa desglosado en cuatro preguntas y seis FAQ que desarman las objeciones de precio y tiempo.',
        learn: 'Para vender un servicio de marketing, la web tiene que demostrar el marketing. Cada sección se ordenó como un argumento y no como un apartado del sitio.' },
      en: { cat: 'Web Design + UX/UI', title: 'Baltazar Aguiar', role: 'LCS · Web Design & Development', client: 'Baltazar Aguiar · Restaurant marketing',
        problem: 'Baltazar advises restaurant owners and has a community of nearly thirty thousand people, but all his authority lived on Instagram and TikTok. With no site of his own, a follower ready to hire him had nowhere to understand the offer or see proof that the system works.',
        goal: 'Turn audience into clients: a sales landing organizing diagnosis, method, results and program, ending in a booked call.',
        steps: [['01','Discover','Real owner objections before hiring'],['02','Define','Sales structure: diagnosis → method → proof → offer'],['03','Design','Dark editorial direction, display type and big numbers'],['04','Deliver','Next.js build, responsive, with WhatsApp CTA']],
        result: 'A long conversion landing: a three-cause diagnosis, a four-stage method, a results block with figures ($26M monthly revenue up from $15M, 20+ businesses, ×2 on average), four short cases, the program broken into four questions, and six FAQs dismantling price and time objections.',
        learn: 'To sell a marketing service, the site has to demonstrate the marketing. Every section was ordered as an argument, not as a page area.' }
    },
    p9: {
      year: '2026', url: 'danielvilla.vercel.app', full: ['danielvilla-fullpage-v3.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript', 'Supabase'],
      es: { cat: 'Diseño Web + Producto', title: 'Daniel Villa Real Estate', role: 'LCS · Diseño, Desarrollo & Panel', client: 'Daniel Villa Real Estate · Santiago del Estero 841, Salta',
        problem: 'Daniel Villa es corredor inmobiliario matriculado —matrícula 558 CUCIS— con veintidós años de trayectoria ininterrumpida desde los dieciocho, millones de reproducciones en TikTok e Instagram, y su empresa fue reconocida por el portal inmobiliario más importante de Argentina como la mejor inmobiliaria de Salta. Todo ese alcance moría en el feed: cada propiedad se publicaba suelta, sin ficha con precio y metros, sin nada que reuniera lo ya vendido, y con el catálogo dependiendo de que alguien lo actualizara a mano cada vez que cambiaba un precio.',
        goal: 'Convertir el alcance de las redes en un catálogo propio, filtrable y actualizable por él mismo, y poner las operaciones ya cerradas al frente como prueba comercial para captar al propietario que todavía no decidió con quién vender.',
        steps: [['01','Descubrir','Qué mira el comprador salteño antes de pedir una visita, y qué necesita ver el que quiere vender'],['02','Definir','Cuatro pilares: propiedades filtrables, zonas, vendidas y tasación'],['03','Diseñar','Estética sobria de real estate, foto grande y ficha legible de un vistazo'],['04','Entregar','Sitio de siete páginas más panel privado con Supabase para autogestión']],
        result: 'Sitio en vivo de siete páginas. El catálogo cruza operación (venta o alquiler), tipo (casa, departamento, terreno), zona y orden por precio, y cada ficha muestra lo que define la decisión —desde una casa a estrenar de tres dormitorios en Vía Aurelia por USD 120.000 hasta un monoambiente en alquiler en El Huaico por ARS 390.000 al mes—; una página de vendidas con seis operaciones cerradas y su precio real a la vista; cinco zonas de Salta explicadas por lo que significan para el comprador (Vía Aurelia frente al aeropuerto, Tres Cerritos, Plaza Alvarado, El Huaico, San Lorenzo); una tasación que pide cuatro datos y sigue por WhatsApp en vez de un formulario eterno; y la página de Daniel con sus videos de TikTok e Instagram embebidos, que es donde la gente ya lo conoce. Detrás, un panel privado con Supabase para cargar, ordenar, editar, subir fotos y marcar una propiedad como vendida sin tocar código.',
        learn: 'En inmobiliaria, publicar lo vendido convence más que publicar lo disponible: es la única prueba de que el trabajo se cierra, y por eso las vendidas tienen página propia y no un renglón al pie. La otra decisión que sostiene el sitio es que el cliente pueda actualizarlo solo: un catálogo que depende de terceros para cambiar un precio envejece en una semana.' },
      en: { cat: 'Web Design + Product', title: 'Daniel Villa Real Estate', role: 'LCS · Design, Development & Admin panel', client: 'Daniel Villa Real Estate · Santiago del Estero 841, Salta',
        problem: 'Daniel Villa is a licensed real estate broker — licence 558 CUCIS — with twenty-two years in the trade without a break since he was eighteen, millions of views on TikTok and Instagram, and an agency named the best in Salta by Argentina\'s largest property portal. All that reach died in the feed: every property posted standalone, with no listing page carrying price and area, nothing gathering what had already sold, and a catalogue that depended on someone updating it by hand every time a price moved.',
        goal: 'Turn the social reach into an owned catalogue — filterable and updatable by him alone — and put closed deals up front as commercial proof to win over owners who have not yet chosen who sells for them.',
        steps: [['01','Discover','What buyers in Salta check before asking for a viewing, and what a seller needs to see'],['02','Define','Four pillars: filterable listings, areas, sold properties and valuation'],['03','Design','Sober real-estate aesthetic, big photography, a listing readable at a glance'],['04','Deliver','A seven-page site plus a private Supabase-backed admin panel']],
        result: 'A live seven-page site. The catalogue cross-filters by operation (sale or rental), type (house, apartment, plot), area and price order, and each listing shows what actually drives the decision — from a new-build three-bedroom house in Vía Aurelia at USD 120,000 to a studio flat to rent in El Huaico at ARS 390,000 a month —; a sold page with six closed deals and their real prices on show; five Salta neighbourhoods explained by what they mean to a buyer (Vía Aurelia facing the airport, Tres Cerritos, Plaza Alvarado, El Huaico, San Lorenzo); a valuation flow asking four fields and continuing on WhatsApp instead of an endless form; and Daniel\'s own page with his TikTok and Instagram videos embedded, since that is where people already know him. Behind it, a private Supabase panel to add, reorder, edit, upload photos and mark a property as sold without touching code.',
        learn: 'In real estate, publishing what sold convinces more than publishing what is available: it is the only proof the work closes, which is why sold properties get their own page rather than a footnote. The other decision holding the site up is that the client can update it alone — a catalogue that needs a third party to change a price ages within a week.' }
    },
    p10: {
      year: '2026', url: 'totalgymsalta.vercel.app', full: ['totalgym-fullpage-v3.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Total Gym Salta', role: 'LCS · Diseño & Desarrollo Web', client: 'Total Gym Salta · Vicente López 770 y Leguizamón 321',
        problem: 'Total Gym opera dos sedes con lógicas de reserva distintas: la matriz de Vicente López 770, con sala de musculación de 7 a 22 y clases grupales, y el studio Pilates Reformer Total de Leguizamón 321, que trabaja con turnos por hora en grupos reducidos. Contarlas juntas confundía —cada actividad tiene su horario y su sede— y separarlas en dos sitios partía la marca en dos.',
        goal: 'Unificar ambas sedes en una sola web sin que ninguna pierda identidad, y que cualquier consulta termine en el WhatsApp de la sede que corresponde, con la clase de prueba como puerta de entrada.',
        steps: [['01','Descubrir','Público distinto de cada sede y qué horario busca cada uno'],['02','Definir','Una marca, dos sedes: jerarquía, horarios y WhatsApp propios'],['03','Diseñar','Sistema negro y amarillo de alto contraste, con foto de entrenamiento real'],['04','Entregar','Sitio responsive con horarios por pestaña y banda de promo editable']],
        result: 'One-page con las dos sedes diferenciadas desde el hero y sus disciplinas listadas. Seis actividades con su turno real (musculación 7—22 y sábados 9—13, boxeo lunes, miércoles y viernes 21 hs, funcional en varios turnos), horarios navegables por pestañas para no estirar la página, sección propia del reformer con sus franjas de mañana (7—11) y tarde (14—21), estética corporal con criolipólisis y bronceado, tres planes comparables (Pase Libre, Full Gym + Clases y Reformer) y el WhatsApp de cada sede por separado, más una banda superior para promos como el 40% del Día del Amigo.',
        learn: 'Dos sedes no son dos sitios: son dos jerarquías dentro del mismo relato. Separar los horarios por pestañas evitó la página kilométrica sin esconder información, y dar un WhatsApp por sede evitó que la consulta llegue al lugar equivocado.' },
      en: { cat: 'Web Design + UX/UI', title: 'Total Gym Salta', role: 'LCS · Web Design & Development', client: 'Total Gym Salta · Vicente López 770 & Leguizamón 321',
        problem: 'Total Gym runs two locations with different booking logics: the main gym at Vicente López 770, with a weights floor open 7am–10pm plus group classes, and the Pilates Reformer Total studio at Leguizamón 321, which works by the hour in small groups. Telling them together confused —every activity has its own schedule and location— and splitting them into two sites broke the brand in half.',
        goal: 'Unify both locations in one site without either losing identity, and route every enquiry to the right location\'s WhatsApp, with the trial class as the entry point.',
        steps: [['01','Discover','Each location\'s distinct audience and the hours they look for'],['02','Define','One brand, two locations: own hierarchy, schedules and WhatsApp'],['03','Design','High-contrast black and yellow system with real training photography'],['04','Deliver','Responsive site with tabbed schedules and an editable promo bar']],
        result: 'A one-pager distinguishing both locations from the hero, with their disciplines listed. Six activities with real time slots (weights 7am–10pm and Saturdays 9am–1pm, boxing Mon/Wed/Fri at 9pm, functional across several slots), tab-navigable schedules to avoid stretching the page, a dedicated reformer section with morning (7–11) and afternoon (14–21) bands, body aesthetics with cryolipolysis and tanning, three comparable plans (Open Pass, Full Gym + Classes and Reformer), a separate WhatsApp per location, and a top bar for promos like the 40% off Friend\'s Day deal.',
        learn: 'Two locations are not two sites: they are two hierarchies inside one story. Tabbed schedules avoided an endless page without hiding information, and a WhatsApp per location kept enquiries from landing in the wrong place.' }
    },
    p11: {
      year: '2026', url: 'hotelposadadelsol.vercel.app', full: ['posadadelsol-fullpage-v2.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Hotel Posada del Sol', role: 'LCS · Diseño & Desarrollo Web', client: 'Hotel Posada del Sol · Salta capital',
        problem: 'Hotel 3★ en Alvarado 646, a metros de la peatonal, con 8,1 en Booking y más de 2.000 opiniones. Todas esas reservas llegaban por plataformas que se llevan su comisión, y el hotel no tenía un canal propio que compitiera con ellas.',
        goal: 'Recuperar la reserva directa: dejar claro que reservando en el sitio se paga menos, y bajar la fricción a un WhatsApp con respuesta humana.',
        steps: [['01','Descubrir','Por qué el huésped reserva en plataformas y qué lo haría cambiar'],['02','Definir','Argumento central: mismo hotel, mejor precio, sin comisiones'],['03','Diseñar','Sistema cálido con buscador de disponibilidad arriba de todo'],['04','Entregar','Sitio bilingüe ES/EN, responsive, con WhatsApp directo']],
        result: 'Sitio bilingüe con buscador de fechas y huéspedes en el hero, cinco tipos de habitación con capacidad y equipamiento, distancias reales a los puntos turísticos (peatonal 2 min, Catedral y MAAM 5 min, teleférico 1 km), doce servicios, el restaurante Bávaro y testimonios de Booking y TripAdvisor. El mensaje "reservá directo y pagá menos" se repite en hero, banda y footer.',
        learn: 'Contra las OTAs no se compite con fotos: se compite con precio explícito y respuesta humana. Poner el ahorro en palabras, y no insinuarlo, es todo el argumento.' },
      en: { cat: 'Web Design + UX/UI', title: 'Hotel Posada del Sol', role: 'LCS · Web Design & Development', client: 'Hotel Posada del Sol · Salta',
        problem: 'A 3★ hotel at Alvarado 646, steps from the pedestrian street, rated 8.1 on Booking with over 2,000 reviews. All those bookings came through platforms taking their commission, and the hotel had no owned channel to compete.',
        goal: 'Win back direct booking: make it clear that booking on the site costs less, and reduce friction to a WhatsApp with a human reply.',
        steps: [['01','Discover','Why guests book on platforms and what would change that'],['02','Define','Core argument: same hotel, better price, no commissions'],['03','Design','Warm system with an availability search above everything'],['04','Deliver','Bilingual ES/EN responsive site with direct WhatsApp']],
        result: 'A bilingual site with a date and guest search in the hero, five room types with capacity and amenities, real walking distances to landmarks (pedestrian street 2 min, Cathedral and MAAM 5 min, cable car 1 km), twelve services, the Bávaro restaurant and Booking/TripAdvisor testimonials. "Book direct and pay less" repeats in hero, banner and footer.',
        learn: 'You do not beat OTAs with photos: you beat them with an explicit price and a human reply. Putting the saving into words, rather than implying it, is the whole argument.' }
    },
    p12: {
      year: '2026', url: 'la-vieja-estacion.vercel.app', full: ['viejaestacion-fullpage-v2.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Peña La Vieja Estación', role: 'LCS · Diseño & Desarrollo Web', client: 'La Vieja Estación · Paseo Balcarce, Salta',
        problem: 'La peña más conocida de la Balcarce —4,5 estrellas con 9.500 reseñas en Google, #9 de 377 en TripAdvisor y 35.000 seguidores— dependía de terceros para algo tan básico como explicar a qué hora empieza el show y cómo se reserva una mesa.',
        goal: 'Ordenar la noche completa en una sola página y llevar la reserva online, que es la acción que el local necesita antes de que el salón se llene.',
        steps: [['01','Descubrir','Dudas del turista: horario, precio, si hace falta reservar'],['02','Definir','La noche como línea de tiempo, de 20:00 a 03:00'],['03','Diseñar','Dirección cálida de peña, con foto de show en vivo'],['04','Entregar','Sitio responsive con reserva de mesa y mapa']],
        result: 'Sitio en vivo con la noche contada como cronología (20:00 puertas, 21:00 cena, 22:00 show con dos grupos de folklore y dos ballets, 03:00 cierre), carta regional de referencia, prueba social arriba, cómo llegar con estacionamiento y reserva de mesa desde cualquier punto del scroll.',
        learn: 'En un espectáculo, la información que más se busca es la más simple: a qué hora empieza. Estructurar la página como una línea de tiempo respondió eso antes de que el visitante tuviera que preguntarlo.' },
      en: { cat: 'Web Design + UX/UI', title: 'Peña La Vieja Estación', role: 'LCS · Web Design & Development', client: 'La Vieja Estación · Paseo Balcarce, Salta',
        problem: 'The best-known peña on Balcarce — 4.5 stars across 9,500 Google reviews, #9 of 377 on TripAdvisor and 35,000 followers — relied on third parties for something as basic as explaining when the show starts and how to book a table.',
        goal: 'Organize the whole night on a single page and move booking online, the action the venue needs before the room fills up.',
        steps: [['01','Discover','Visitor doubts: time, price, whether booking is needed'],['02','Define','The night as a timeline, 20:00 to 03:00'],['03','Design','Warm peña direction with live-show photography'],['04','Deliver','Responsive site with table booking and map']],
        result: 'Live site telling the night as a timeline (20:00 doors, 21:00 dinner, 22:00 show with two folk groups and two ballets, 03:00 close), a reference regional menu, social proof up top, directions with parking, and table booking from anywhere in the scroll.',
        learn: 'For a show, the most-searched information is the simplest: what time it starts. Structuring the page as a timeline answered that before the visitor had to ask.' }
    },
    p13: {
      year: '2026', url: 'lacondesa-one.vercel.app', full: ['lacondesa-fullpage-v3.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'La Condesa', role: 'LCS · Diseño & Desarrollo Web', client: 'La Condesa · Medicina estética · Bucaramanga, Colombia',
        problem: 'La Condesa es un consultorio de medicina estética facial y corporal en el barrio La Aurora de Bucaramanga. Trabaja diez procedimientos muy distintos entre sí —de botox y plasma rico en plaquetas a moldeo de cintura y postoperatorios— y además forma profesionales. Todo eso llegaba mezclado por Instagram, donde la paciente no distinguía qué le correspondía, y donde la promesa fácil de la competencia empujaba a prometer resultados que un consultorio serio no puede garantizar.',
        goal: 'Construir un sitio que venda por criterio clínico y no por promesa: que ordene los diez tratamientos, explique qué esperar de cada uno y ponga la valoración previa —gratuita y sin compromiso— como única puerta de entrada.',
        steps: [['01','Descubrir','Qué pregunta la paciente antes de agendar y qué la frena'],['02','Definir','Arquitectura de tres páginas: facial, corporal y capacitaciones'],['03','Diseñar','Sistema dorado y sobrio, con foto real de procedimiento sin retoque'],['04','Entregar','Sitio multipágina responsive, sin formularios, con WhatsApp directo']],
        result: 'Sitio de seis páginas. El inicio abre con la regla de la casa —ningún tratamiento se aplica sin valorar antes la piel y los antecedentes— y sigue con las dos líneas, la bioseguridad (material de un solo uso, insumos sellados delante de la paciente), quién atiende y una galería de trabajos reales sin retoque. Facial y corporal tienen página propia con sus cinco tratamientos explicados con tiempos concretos: el botox aparece entre el día 3 y el 14 y dura de 4 a 6 meses, el dermapen necesita de 3 a 6 sesiones y deja rojez dos días, los corporales se miden al inicio y al cierre del ciclo. Se completa con capacitaciones, FAQ por área y dos páginas legales adaptadas a la Ley 1581 de Colombia por tratarse de datos de salud.',
        learn: 'En salud, decir que no también vende. Los textos que más confianza generan son los que ponen límites —"si buscás bajar de peso, no es este el camino", "preferimos perder una cita antes que un resultado"—, y por eso el sitio no publica precios: se informan después de la valoración, cuando ya se sabe cuántas sesiones hacen falta.' },
      en: { cat: 'Web Design + UX/UI', title: 'La Condesa', role: 'LCS · Web Design & Development', client: 'La Condesa · Aesthetic medicine · Bucaramanga, Colombia',
        problem: 'La Condesa is a facial and body aesthetic medicine practice in the La Aurora neighbourhood of Bucaramanga. It performs ten very different procedures — from botox and platelet-rich plasma to waist contouring and post-op care — and also trains professionals. All of it arrived mixed together on Instagram, where patients could not tell what applied to them, and where competitors\' easy promises pushed toward guaranteeing results a serious practice cannot.',
        goal: 'Build a site that sells on clinical judgement rather than promises: organize the ten treatments, explain what to expect from each, and make the free, no-obligation assessment the only way in.',
        steps: [['01','Discover','What patients ask before booking and what holds them back'],['02','Define','Three-page architecture: facial, body and training'],['03','Design','Sober gold system with real, unretouched procedure photography'],['04','Deliver','Responsive multi-page site, no forms, direct WhatsApp']],
        result: 'A six-page site. The homepage opens with the house rule — no treatment is applied without first assessing the skin and medical history — then covers both lines, biosafety (single-use materials, supplies unsealed in front of the patient), who provides care, and a gallery of real unretouched work. Facial and body each get their own page with five treatments explained in concrete timeframes: botox appears between day 3 and 14 and lasts four to six months, dermapen needs three to six sessions and leaves redness for two days, body treatments are measured at the start and end of each cycle. It closes with training, per-area FAQs and two legal pages adapted to Colombia\'s Law 1581, since health data is involved.',
        learn: 'In healthcare, saying no also sells. The copy that builds the most trust is the copy that sets limits — "if your goal is weight loss, this is not the way", "we would rather lose an appointment than a result" — which is why the site publishes no prices: they are given after the assessment, once the number of sessions is known.' }
    },
    p14: {
      year: '2026', url: 'pielcanela-spa.vercel.app', full: ['pielcanela-fullpage-v2.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Piel Canela', role: 'LCS · Diseño & Desarrollo Web', client: 'Piel Canela Spa & Bronceo · Bucaramanga, Colombia',
        problem: 'Piel Canela es la primera Casa Rosada de Bucaramanga: un spa de bronceado brasileño que nació del sueño de Dalia Marulanda y ya pasó las 8.000 clientas. Todo ese recorrido vivía en Instagram, donde una clienta nueva no podía entender la diferencia entre terraza, cabina y marcación, ni ver los horarios reales de cada servicio.',
        goal: 'Ordenar los cuatro servicios y sus horarios distintos en un solo lugar, y llevar la reserva al WhatsApp — que es donde el spa efectivamente agenda.',
        steps: [['01','Descubrir','Qué no entiende la clienta nueva: terraza vs. cabina vs. marcación'],['02','Definir','Servicio, resultado y horario propio para cada modalidad'],['03','Diseñar','Sistema rosa Casa Rosa: cálido, femenino y con foto real del lugar'],['04','Entregar','Sitio responsive con WhatsApp flotante y mapa']],
        result: 'Sitio en vivo con los cuatro servicios diferenciados y etiquetados por modalidad (al sol, sin sol, la técnica, piel radiante), un bloque que explica por qué la técnica brasileña da color uniforme y realza la figura, galería de resultados reales, la historia de la Casa Rosa con sus 8.000 clientas, testimonios y la tabla de horarios separada por terraza, cabina y domingos. Reserva por WhatsApp desde cualquier punto del scroll.',
        learn: 'Cuando un negocio vende varias modalidades del mismo servicio, la web tiene que explicar la diferencia antes que el precio. Separar los horarios por modalidad resolvió la consulta que más entraba por mensaje.' },
      en: { cat: 'Web Design + UX/UI', title: 'Piel Canela', role: 'LCS · Web Design & Development', client: 'Piel Canela Spa & Bronceo · Bucaramanga, Colombia',
        problem: 'Piel Canela is Bucaramanga\'s first Casa Rosada: a Brazilian tanning spa born from Dalia Marulanda\'s dream, now past 8,000 clients. All of that lived on Instagram, where a new client could not tell the difference between terrace, booth and body contouring, nor see each service\'s actual hours.',
        goal: 'Organize the four services and their different schedules in one place, and move booking to WhatsApp — where the spa actually schedules.',
        steps: [['01','Discover','What a new client misses: terrace vs. booth vs. contouring'],['02','Define','A service, a result and its own schedule for each option'],['03','Design','Casa Rosa pink system: warm, feminine, with real venue photography'],['04','Deliver','Responsive site with floating WhatsApp and map']],
        result: 'Live site with four clearly distinguished services labelled by mode (in the sun, no sun, the technique, radiant skin), a block explaining why the Brazilian technique yields even colour and enhances the figure, a real results gallery, the Casa Rosa story with its 8,000 clients, testimonials, and a schedule table split by terrace, booth and Sundays. WhatsApp booking from anywhere in the scroll.',
        learn: 'When a business sells several versions of the same service, the site must explain the difference before the price. Splitting schedules by mode answered the question that arrived most often by message.' }
    },
    p15: {
      year: '2026', url: 'hierronort.vercel.app', full: ['hierronort-fullpage.webp'], tools: ['Figma', 'HTML / CSS', 'JavaScript'],
      es: { cat: 'Diseño Web', title: 'Hierronort', role: 'LCS · Diseño & Desarrollo Web', client: 'Hierronort Salta S.R.L. · Av. Paraguay 1450, Salta',
        problem: 'Hierronort distribuye hierro, chapa y materiales de construcción desde 1986, con seis sucursales entre Salta, Jujuy, Tucumán y La Rioja y más de 150 personas trabajando, pero su catálogo de nueve familias de producto —hierros y mallas, perfiles, tubos y caños, chapas, cubiertas, malla y alambre, construcción en seco, impermeabilizantes e instalaciones sanitarias— vivía repartido entre catálogos impresos y el trato con el vendedor de sucursal. Quien cotizaba desde otra provincia no tenía forma de ver stock, sucursales ni pedir precio sin llamar.',
        goal: 'Poner en un solo sitio el catálogo completo, las seis sucursales con su dirección y los sectores que atiende cada una, y convertir cualquier consulta en una cotización online o por WhatsApp.',
        steps: [['01','Descubrir','Cómo cotiza hoy cada sector: construcción, minería, industria y agro'],['02','Definir','Nueve familias de producto y seis sucursales como ejes de navegación'],['03','Diseñar','Sistema industrial rojo y negro, con foto real de depósito y planchado'],['04','Entregar','Sitio responsive con cotizador y mapa de sucursales']],
        result: 'Sitio en vivo con las nueve familias de producto explicadas con sus variantes reales (perfiles C, UPN e IPN; chapas galvanizadas y laminadas; instalaciones por fusión, entre otras), un bloque "Por qué Hierronort" en tres razones —stock propio, entrega puerta a puerta y vendedor asignado por cuenta—, cuatro sectores con foto y acceso a más información, el mapa de las seis sucursales con dirección y provincia, una línea de tiempo desde 1986 hasta la certificación ISO 9001:2015 y el centro de procesamiento de chapa en bobina de 2023, y un formulario de cotización con opción de escribir por WhatsApp.',
        learn: 'En un distribuidor con stock propio, el argumento de venta no es el precio: es la certeza de que el material está ahí, hoy, sin esperar a fábrica. Ordenar el sitio por sector —construcción, minería, industria, agro— en vez de por producto hizo que cada visitante viera primero lo que realmente compra.' },
      en: { cat: 'Web Design', title: 'Hierronort', role: 'LCS · Web Design & Development', client: 'Hierronort Salta S.R.L. · Av. Paraguay 1450, Salta',
        problem: 'Hierronort has distributed steel, sheet metal and construction materials since 1986, with six branches across Salta, Jujuy, Tucumán and La Rioja and over 150 people on staff, but its catalogue of nine product families — rebar and mesh, structural profiles, tubes and pipes, sheet metal, roofing, expanded metal and wire, dry construction, waterproofing and sanitary fittings — lived split between printed catalogues and whatever the branch salesperson could tell you. Anyone quoting from another province had no way to check stock, branches or pricing without a phone call.',
        goal: 'Put the full catalogue, all six branches with address and the sectors each one serves, and turn any enquiry into an online quote or a WhatsApp message.',
        steps: [['01','Discover','How each sector — construction, mining, industry, agriculture — quotes today'],['02','Define','Nine product families and six branches as the navigation backbone'],['03','Design','Industrial red-and-black system with real warehouse and coil photography'],['04','Deliver','Responsive site with a quote request tool and branch map']],
        result: 'A live site with all nine product families explained through their real variants (C, UPN and IPN profiles; galvanized and rolled sheet metal; fusion-welded pipe fittings, among others), a "Why Hierronort" block with three reasons — own stock, door-to-door delivery, an assigned sales rep per account —, four sectors with photography and a link to learn more, a map of all six branches with address and province, a timeline running from 1986 to the 2023 ISO 9001:2015 certification and coil-processing centre, and a quote form with a WhatsApp option.',
        learn: 'For a distributor with its own stock, the sales pitch is not price — it is the certainty that the material is there today, with no factory wait. Ordering the site by sector — construction, mining, industry, agriculture — instead of by product let every visitor see what they actually buy first.' }
    },
    p16: {
      year: '2026', url: 'paraviciniarquitectura.vercel.app', full: ['paravicini-fullpage-v3.webp'], tools: ['Figma', 'Next.js', 'React'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Paravicini Arquitectura', role: 'LCS · Diseño & Desarrollo Web', client: 'Estudio Paravicini · San Lorenzo Chico, Salta',
        problem: 'Paravicini es un estudio familiar de San Lorenzo Chico que proyecta y construye casas de autor en Salta y Tucumán desde 2006, con adobe, teja, piedra y madera. Además de arquitectura lleva dos unidades más —Desarrollos, a cargo de Guido Paravicini, y Propiedades, a cargo de Franca Paravicini—, cada una con consultas y clientes distintos. Toda la obra construida vivía en Instagram, mezclada con el día a día: no había dónde ver una casa con su ubicación, su superficie y su año, ni cómo explicarle a alguien de otra provincia que se puede proyectar a distancia.',
        goal: 'Convertir la obra construida en el argumento del sitio —una ficha por casa, con foto grande, ubicación, metros y año—, explicar el proceso a distancia con plazos reales para quien no puede viajar a Salta, y darle a cada una de las tres unidades su propia puerta y su propio WhatsApp.',
        steps: [['01','Descubrir','Tres audiencias y tres responsables: quién construye, quién invierte y quién compra'],['02','Definir','Catorce páginas: cada obra con ficha propia, estudio, distancia, desarrollos y propiedades'],['03','Diseñar','Dirección editorial cálida sobre foto de obra a pantalla completa'],['04','Entregar','Sitio en Next.js, sin formularios: cada consulta va al WhatsApp que corresponde']],
        result: 'Sitio en vivo de catorce páginas construido en Next.js. Seis obras con ficha propia y navegación entre ellas —Casa San Lorenzo Chico (San Lorenzo Chico, 320 m², 2023), Casa Patio de Adobe (Vaqueros, 280 m², 2022), Casa Galería (Cerrillos, 240 m², 2021), Refugio en el Cerro (La Caldera, 160 m², 2024), Taller Paravicini (San Lorenzo Chico, 90 m², 2020) y Casa Miradores (Tafí del Valle, Tucumán, 300 m², 2023)—; una página de estudio con las cinco etapas del trabajo, del primer encuentro a la entrega de llaves; "Proyectos a distancia" con los cuatro pasos y sus plazos de referencia —1 semana, 3 a 4 semanas, 6 a 8 semanas y acompañamiento durante toda la obra—, la lista de lo que se entrega y cuatro preguntas frecuentes; y las unidades Desarrollos, con Palmas Plaza en comercialización, y Propiedades, cada una con su responsable y su WhatsApp directo.',
        learn: 'El sitio no tiene un solo formulario: todo termina en el WhatsApp de la persona que corresponde. En un estudio de tres personas con tres negocios, esa decisión hizo más que cualquier campo de contacto, porque la consulta llega directo a quien la puede responder. Y publicar cada casa con ubicación, metros y año convirtió la obra en prueba: se deja de prometer y se muestra.' },
      en: { cat: 'Web Design + UX/UI', title: 'Paravicini Arquitectura', role: 'LCS · Web Design & Development', client: 'Estudio Paravicini · San Lorenzo Chico, Salta',
        problem: 'Paravicini is a family studio in San Lorenzo Chico that has designed and built author-driven houses across Salta and Tucumán since 2006, working in adobe, tile, stone and timber. Beyond architecture it runs two more units — Developments, led by Guido Paravicini, and Properties, led by Franca Paravicini — each with its own clients and enquiries. All the built work lived on Instagram, mixed in with day-to-day posts: there was nowhere to see a house with its location, its floor area and its year, and no way to explain to someone in another province that the studio can design remotely.',
        goal: 'Make the built work the argument of the site — one page per house, with a large photo, location, square metres and year —, explain the remote process with real timeframes for clients who cannot travel to Salta, and give each of the three units its own door and its own WhatsApp line.',
        steps: [['01','Discover','Three audiences and three leads: who builds, who invests and who buys'],['02','Define','Fourteen pages: a page per project, plus studio, remote work, developments and properties'],['03','Design','Warm editorial direction over full-screen built-work photography'],['04','Deliver','A Next.js site with no forms: every enquiry goes to the right WhatsApp']],
        result: 'A live fourteen-page site built in Next.js. Six projects with their own page and navigation between them — Casa San Lorenzo Chico (San Lorenzo Chico, 320 m², 2023), Casa Patio de Adobe (Vaqueros, 280 m², 2022), Casa Galería (Cerrillos, 240 m², 2021), Refugio en el Cerro (La Caldera, 160 m², 2024), Taller Paravicini (San Lorenzo Chico, 90 m², 2020) and Casa Miradores (Tafí del Valle, Tucumán, 300 m², 2023) —; a studio page with the five stages of the work, from first meeting to handover; a "Remote projects" page with four steps and their reference timeframes — 1 week, 3 to 4 weeks, 6 to 8 weeks and support throughout construction —, the list of deliverables and four FAQs; and the Developments unit, with Palmas Plaza now selling, alongside Properties, each with its lead named and its direct WhatsApp.',
        learn: 'The site does not have a single form: everything ends in the WhatsApp of the person who should answer. For a three-person studio running three businesses, that decision did more than any contact field, because the enquiry reaches whoever can actually reply. And publishing every house with its location, floor area and year turned the built work into proof: you stop promising and start showing.' }
    },
    p17: {
      year: '2026', url: 'todosaridosalta.vercel.app', full: ['todoaridos-fullpage-v2.webp'], tools: ['Figma', 'Next.js', 'React'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Todo Áridos Salta', role: 'LCS · Diseño & Desarrollo Web', client: 'Todo Áridos Salta · Norte Piscinas · Salta',
        problem: 'Todo Áridos Salta hace dos cosas que el cliente ve como una sola: vende áridos y mueve suelos con equipos propios desde 2020, y con esos mismos equipos construye piscinas en Salta capital, San Lorenzo, Vaqueros y la zona sur. Su ventaja real —que el pozo y la pileta los hace la misma gente, sin un tercero que atrase la obra— no aparecía en ningún lado, y la pregunta que reciben todos los días, hormigón o fibra de vidrio, se contestaba de nuevo en cada conversación.',
        goal: 'Separar las dos líneas del negocio sin partir la empresa en dos, contestar de una vez la comparación entre hormigón y fibra, y convertir cada visita en un presupuesto que llegue por WhatsApp con los datos de la obra ya cargados.',
        steps: [['01','Descubrir','Las dos entradas al negocio: el que quiere una pileta y el que necesita áridos'],['02','Definir','Piscinas por tipo de construcción y obras filtrables por zona'],['03','Diseñar','Sistema de obra en naranja y negro, con foto real de cada pileta terminada'],['04','Entregar','Sitio responsive con presupuesto en cuatro pasos que abre WhatsApp escrito']],
        result: 'Sitio en vivo de dieciséis páginas hecho en Next.js. Dos páginas de producto, hormigón y fibra de vidrio, cada una con el proceso en cinco pasos —relevamiento, excavación con equipos propios, estructura o colocación del casco, terminaciones y llenado— y sus preguntas frecuentes; seis obras con ficha propia, filtrables por tipo y por zona, y cada una abierta con el par del terreno excavado y la pileta terminada; una página de áridos y movimiento de suelos con los siete materiales que venden (arena mediana, lavada y ripiosa, ripio, enlame, base y relleno) y los cuatro servicios de máquina; una página para clubes e instituciones; y un pedido de presupuesto en cuatro pasos que termina abriendo WhatsApp con la consulta ya redactada.',
        learn: 'La página de clubes dice, con todas las letras, que todavía no hicieron una obra de ese tamaño, y ofrece en cambio los equipos propios y la capacidad técnica. Decirlo de frente convierte una debilidad en el argumento más creíble del sitio: el que lee sabe que lo que sí afirman es cierto.' },
      en: { cat: 'Web Design + UX/UI', title: 'Todo Áridos Salta', role: 'LCS · Web Design & Development', client: 'Todo Áridos Salta · Norte Piscinas · Salta',
        problem: 'Todo Áridos Salta does two things its customers see as one: it has sold aggregates and moved earth with its own machinery since 2020, and with that same machinery it builds swimming pools across Salta city, San Lorenzo, Vaqueros and the southern zone. Its real edge — the same crew digs the hole and builds the pool, with no third party to delay the job — appeared nowhere, and the question they get every single day, concrete or fibreglass, was answered from scratch in every conversation.',
        goal: 'Separate the two business lines without splitting the company in two, settle the concrete-versus-fibreglass comparison once, and turn every visit into a quote that arrives on WhatsApp with the job details already filled in.',
        steps: [['01','Discover','The two ways in: someone who wants a pool, someone who needs aggregates'],['02','Define','Pools by construction type and projects filterable by area'],['03','Design','A site-work system in orange and black, with real photos of every finished pool'],['04','Deliver','Responsive site with a four-step quote that opens WhatsApp pre-written']],
        result: 'A live sixteen-page site built in Next.js. Two product pages, concrete and fibreglass, each with the five-step process — survey, excavation with in-house machinery, structure or shell placement, finishes and filling — and its own FAQs; six projects with their own page, filterable by type and area, each opening with the pair of the excavated ground and the finished pool; an aggregates and earthworks page listing the seven materials they sell (medium, washed and gravelly sand, gravel, silt, base and fill) plus four machinery services; a page for clubs and institutions; and a four-step quote request that ends by opening WhatsApp with the enquiry already written.',
        learn: 'The clubs page states outright that they have never built a pool that size, and offers their own machinery and technical capacity instead. Saying it plainly turns a weakness into the most credible argument on the site: whoever reads it knows that what they do claim is true.' }
    },
    p18: {
      year: '2026', url: 'jms-constructora.vercel.app', full: ['jms-fullpage-v2.webp'], tools: ['Figma', 'Next.js', 'React'],
      es: { cat: 'Diseño Web + UX/UI', title: 'JMS Constructora', role: 'LCS · Diseño & Desarrollo Web', client: 'JMS Constructora · Av. 44 N.º 1387, La Plata',
        problem: 'JMS lleva treinta años levantando edificios en La Plata con obra propia, escriturada y sin comisión: no revenden como una inmobiliaria, construyen desde el pozo hasta la entrega. Tenían un edificio recién entregado (Amics I), uno en obra a tres cuadras (Amics II) y un loteo con la infraestructura hecha (Aires del Pinar), pero nada de eso —ni las unidades sueltas que quedaban disponibles, ni el avance real de la obra en curso— tenía dónde mostrarse con la prueba puesta en fecha.',
        goal: 'Separar los tres emprendimientos con su estado real a la vista, publicar cada unidad disponible con su precio en dólares y filtrarlas por edificio, ambientes y metros, y convertir el avance de obra en un registro fechado mes a mes que demuestre que el edificio en pozo realmente se está construyendo.',
        steps: [['01','Descubrir','Los tres estados de una desarrolladora: entregado, en obra y en lotes'],['02','Definir','Unidades filtrables por edificio, ambientes, metros y estado —incluidas las vendidas, en gris, como prueba'],['03','Diseñar','Sistema editorial en verde sobre negro, con foto real de cada edificio'],['04','Entregar','Sitio responsive con el avance de obra fechado y WhatsApp directo']],
        result: 'Sitio en vivo de dieciséis páginas hecho en Next.js. Tres emprendimientos con ficha propia —Amics I, entregado y con PH aprobado para escriturar ya, calle 42 entre 14 y 15; Amics II, en obra a tres cuadras, con la estructura levantada a cinco niveles fotografiada el 17 de julio de 2026 y el registro de meses anteriores sumándose a medida que avanza; y Aires del Pinar, el loteo en San Carlos con calles asfaltadas, alumbrado y forestación ya puestos—; un listado de siete unidades disponibles con precio (Amics I 3° C, 2 ambientes, 48,5 m², contrafrente, USD 87.885) filtrable por edificio, ambientes, metros y estado, mostrando también las vendidas y reservadas como prueba de lo que ya se colocó; una sección de viviendas a terceros con el antes y después de Casa FF, entregada, y Casa DJ en marcha; y la página de la empresa con las cinco preguntas que se hacen antes de comprar en pozo.',
        learn: 'En una desarrolladora, la desconfianza no se vence explicando el proceso: se vence con fecha. Por eso Amics II no se vende con un render y una promesa, sino con una foto de obra fechada mes a mes desde el pozo, y por eso las unidades vendidas quedan visibles en gris en vez de borrarse: son la prueba de que otros ya compraron.' },
      en: { cat: 'Web Design + UX/UI', title: 'JMS Constructora', role: 'LCS · Web Design & Development', client: 'JMS Constructora · Av. 44 N.º 1387, La Plata',
        problem: 'JMS has spent thirty years putting up buildings in La Plata with its own stock, delivered with clean title and no commission: they do not resell like an estate agency, they build from the ground up to handover. They had one building just delivered (Amics I), one under construction three blocks away (Amics II) and a lot subdivision with the infrastructure already in (Aires del Pinar), but none of it — not the individual units still available, not the real progress of the ongoing build — had anywhere to show itself with dated proof.',
        goal: 'Show the three developments with their real status up front, publish every available unit with its price in dollars and let buyers filter by building, rooms and area, and turn the construction progress into a dated month-by-month record proving the off-plan building is actually being built.',
        steps: [['01','Discover','A developer\'s three states: delivered, under construction, and lots'],['02','Define','Units filterable by building, rooms, area and status — sold ones included, greyed out, as proof'],['03','Design','An editorial system in green on black, with real photography of each building'],['04','Deliver','Responsive site with dated construction progress and direct WhatsApp']],
        result: 'A live sixteen-page site built in Next.js. Three developments with their own page — Amics I, delivered and cleared to transfer title with its co-ownership bylaws approved, on calle 42 between 14 and 15; Amics II, under construction three blocks away, its structure raised to five storeys as photographed on 17 July 2026, with earlier months\' progress added as the build advances; and Aires del Pinar, the San Carlos lot subdivision with paved streets, street lighting and landscaping already in place —; a listing of seven available units with pricing (Amics I 3rd floor C, 2 rooms, 48.5 m², rear-facing, USD 87,885) filterable by building, rooms, area and status, showing sold and reserved units too, greyed out, as proof of what has already moved; a third-party housing section with the before-and-after of Casa FF, delivered, and Casa DJ, underway; and the company page answering the five questions buyers ask before buying off-plan.',
        learn: 'For a developer, distrust is not overcome by explaining the process — it is overcome with a date. That is why Amics II is not sold with a render and a promise but with construction photos dated month by month from the ground up, and why sold units stay visible, greyed out, instead of disappearing: they are proof that others already bought in.' }
    },
    p19: {
      year: '2026', url: 'dr-petersen-pfister.vercel.app', full: ['petersen-fullpage.webp'], tools: ['Figma', 'Next.js', 'React'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Dr. Petersen Pfister', role: 'LCS · Diseño & Desarrollo Web', client: 'Dr. Ezequiel Sergio Petersen Pfister · M.P. 5397 · Salta',
        problem: 'El Dr. Petersen Pfister es especialista en cirugía plástica, estética y reparadora, socio titular de la Sociedad Argentina de Cirugía Plástica regional Noroeste, con la práctica centrada en cirugía mamaria y contorno corporal. Su reputación estaba repartida entre plataformas de terceros —4,9 con 129 valoraciones en Crisalix, 5,0 en Esteticas.com.ar— y 18.800 seguidores en Instagram, con la dirección del consultorio apareciendo distinta según el directorio. Lo que más ansiedad genera antes de una cirugía no es la cirugía: es no saber qué va a pasar, y eso no estaba escrito en ningún lado.',
        goal: 'Explicar cada procedimiento con la misma seriedad con la que se explica en el consultorio —cómo se hace, la anestesia, la recuperación día por día y los riesgos—, unificar los datos de contacto en una sola fuente y no prometer resultados en ningún lugar del sitio.',
        steps: [['01','Descubrir','Qué se pregunta antes de operarse y qué no se anima a preguntar'],['02','Definir','Diez procedimientos con página propia, agrupados por mama, cuerpo y rostro'],['03','Diseñar','Sistema clínico en azul y gris claro, sin lenguaje de venta'],['04','Entregar','Sitio responsive con turno por WhatsApp y aviso médico']],
        result: 'Sitio en vivo hecho en Next.js, con veinte páginas indexables. Diez procedimientos explicados uno por uno —aumento mamario, mastopexia, reducción y reconstrucción mamaria, ginecomastia, abdominoplastia, lipoescultura, rinoplastia, blefaroplastia y otoplastia—, cada uno con su técnica, su recuperación y sus riesgos; una galería de antes y después que se filtra por procedimiento, zona y tiempo transcurrido en vez de scrollear al infinito; el proceso en cuatro etapas, de la consulta de cuarenta minutos al posoperatorio; las valoraciones publicadas siempre con la plataforma de origen al lado; y un bloque que fija los datos del consultorio con una frase clara: si los encuentra distintos en algún directorio, los que valen son estos.',
        learn: 'En salud el diseño se juega en lo que no se promete. Las fichas de resultados dicen que son de ejemplo, los riesgos se listan antes que los beneficios y las valoraciones llevan la fuente al lado. Publicado como versión de muestra para revisión del doctor: las fotos de resultados esperan su material y el consentimiento de cada paciente, y hasta entonces el sitio no está indexado.' },
      en: { cat: 'Web Design + UX/UI', title: 'Dr. Petersen Pfister', role: 'LCS · Web Design & Development', client: 'Dr. Ezequiel Sergio Petersen Pfister · M.P. 5397 · Salta',
        problem: 'Dr. Petersen Pfister is a specialist in plastic, aesthetic and reconstructive surgery, a full member of the Argentine Society of Plastic Surgery, Northwest chapter, with a practice centred on breast surgery and body contouring. His reputation was scattered across third-party platforms — 4.9 from 129 ratings on Crisalix, 5.0 on Esteticas.com.ar — and 18,800 Instagram followers, with the clinic address showing up differently in every directory. What causes the most anxiety before surgery is not the surgery: it is not knowing what will happen, and that was written down nowhere.',
        goal: 'Explain every procedure with the same seriousness used in consultation — how it is done, the anaesthesia, the day-by-day recovery and the risks —, unify the contact details into a single source, and promise results nowhere on the site.',
        steps: [['01','Discover','What patients ask before surgery, and what they do not dare ask'],['02','Define','Ten procedures with their own page, grouped by breast, body and face'],['03','Design','A clinical system in blue and light grey, with no sales language'],['04','Deliver','Responsive site with WhatsApp appointments and a medical disclaimer']],
        result: 'A live site built in Next.js, with twenty indexable pages. Ten procedures explained one by one — breast augmentation, mastopexy, breast reduction and reconstruction, gynecomastia, abdominoplasty, liposculpture, rhinoplasty, blepharoplasty and otoplasty —, each with its technique, recovery and risks; a before-and-after gallery filtered by procedure, area and time elapsed instead of endless scrolling; the process in four stages, from the forty-minute consultation to follow-up care; published ratings always shown next to the platform they come from; and a block pinning down the clinic details with one clear line: if you find them different in any directory, these are the ones that count.',
        learn: 'In healthcare, design is decided by what you refuse to promise. The result cards say they are examples, risks are listed before benefits, and every rating carries its source. Published as a review version for the doctor: the result photos await his material and each patient consent, and until then the site stays out of search engines.' }
    },
    p20: {
      year: '2026', url: 'vero-saguier.vercel.app', full: ['verosaguier-fullpage-v2.webp', 'verosaguier-fullpage2-v2.webp'], tools: ['Figma', 'Next.js', 'React'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Vero Saguier', role: 'LCS · Diseño & Desarrollo Web', client: 'Vero Saguier · Diseño del paisaje · Salta y Buenos Aires',
        problem: 'Vero Saguier proyecta y dirige jardines privados y espacios públicos en Salta y en Buenos Aires. Se formó en la Escuela Pampa Infinita, afiliada a la John Brookes School inglesa, y egresó con la máxima nota; su jardín de Los Zarzos, en Villa San Lorenzo, salió publicado en La Nación, Revista Jardín. Su trabajo se ordenaba como se ordenan casi todos los sitios de paisajismo —una galería de fotos lindas—, cuando lo que define un jardín suyo no es el estilo sino el lugar: en la selva de montaña y en el valle seco no se comparte ni una sola especie.',
        goal: 'Convertir la ecorregión en el eje del sitio, para que cada proyecto se entienda desde el territorio donde está, y sostener el criterio de que el jardín se piensa junto con la arquitectura y no después.',
        steps: [['01','Descubrir','Cómo piensa un jardín: primero el lugar, después las plantas'],['02','Definir','Diez proyectos cruzables por tipo, escala y ecorregión'],['03','Diseñar','Dirección editorial oscura, con la foto del jardín a página completa'],['04','Entregar','Sitio responsive, sin cookies ni base de datos']],
        result: 'Sitio en vivo hecho en Next.js, con quince páginas. Diez proyectos con ficha propia que se cruzan por tipo —jardín privado, espacio público, paisaje productivo—, por escala y por las tres ecorregiones en las que trabaja: yunga, pastizal y valle seco, cada una explicada por lo que le exige a la plantación. La ficha de Los Zarzos cuenta la obra completa: un terreno que bajaba nueve metros entre la calle y el fondo, resuelto en terrazas con escaleras de durmientes, un rosedal de variedades inglesas y de té, gramíneas y tipas en los bordes, y la convocatoria llegando antes de que empezara la casa. El formulario no guarda nada: arma el mail en el programa de correo de quien escribe.',
        learn: 'Ordenar la obra por ecorregión en vez de por estilo hace visible el argumento del oficio: un jardín tiene alma cuando es fiel al territorio donde está. Publicado como versión de muestra para su revisión —salvo Los Zarzos, los nombres, los años y las superficies esperan su confirmación, y tres imágenes están generadas con inteligencia artificial y así se declara en el pie del sitio.' },
      en: { cat: 'Web Design + UX/UI', title: 'Vero Saguier', role: 'LCS · Web Design & Development', client: 'Vero Saguier · Landscape design · Salta and Buenos Aires',
        problem: 'Vero Saguier designs and directs private gardens and public spaces in Salta and Buenos Aires. She trained at Escuela Pampa Infinita, affiliated with the English John Brookes School, graduating with top marks; her garden at Los Zarzos, in Villa San Lorenzo, was published in La Nación, Revista Jardín. Her work was organised the way almost every landscape site is organised — a gallery of pretty photos — when what defines one of her gardens is not style but place: a mountain rainforest and a dry valley do not share a single species.',
        goal: 'Make the ecoregion the backbone of the site, so every project is understood from the territory it belongs to, and hold the argument that a garden is designed alongside the architecture, not after it.',
        steps: [['01','Discover','How she thinks a garden: the place first, the plants after'],['02','Define','Ten projects cross-filtered by type, scale and ecoregion'],['03','Design','Dark editorial direction with full-page garden photography'],['04','Deliver','Responsive site with no cookies and no database']],
        result: 'A live fifteen-page site built in Next.js. Ten projects with their own page, cross-filtered by type — private garden, public space, productive landscape —, by scale and by the three ecoregions she works in: yunga, grassland and dry valley, each explained by what it demands of the planting. The Los Zarzos page tells the whole job: a plot dropping nine metres from street to rear boundary, resolved in terraces with sleeper stairs, a rose garden of English and tea varieties, grasses and tipa trees along the edges, and a commission that arrived before the house was even started. The contact form stores nothing: it composes the email in the visitor own mail client.',
        learn: 'Ordering the work by ecoregion instead of by style makes the argument of the craft visible: a garden has a soul when it is faithful to the territory it sits in. Published as a review version — apart from Los Zarzos, the names, years and areas await her confirmation, and three images are AI-generated, as the site footer states.' }
    },
    p21: {
      year: '2026', url: 'van-strate-cortese.vercel.app', full: ['vanstrate-fullpage.webp'], tools: ['Figma', 'Next.js', 'React'],
      es: { cat: 'Diseño Web + UX/UI', title: 'Van Strate Cortese', role: 'LCS · Diseño & Desarrollo Web', client: 'Arq. Alejandra Van Strate · Arq. Santiago Cortese · Santa Fe capital',
        problem: 'Alejandra Van Strate y Santiago Cortese son dos arquitectos que proyectan y dirigen obra desde Santa Fe, sin estructura de estudio de por medio: los mismos dos están al frente desde el proyecto hasta la entrega, y resuelven vivienda, locales comerciales y obra industrial. Toda su obra vivía en Instagram —132 publicaciones y 8.553 seguidores en @vcestudio.arq—, donde una planta industrial completa y una cocina terminada compiten en el mismo cuadrado y el trabajo se hunde en el feed a las dos semanas. No tenían dónde mostrar que el estudio hace las tres cosas ni cómo se resolvió cada obra.',
        goal: 'Sacar la obra del feed y ordenarla por lo que el estudio realmente sabe hacer —vivienda, comercial e industria—, para que un cliente industrial entienda que puede encargarles una nave sin dudar de que también hacen casas.',
        steps: [['01','Descubrir','Qué obra tienen, cuál abre puertas y cuál está a confirmar'],['02','Definir','Seis obras filtrables por las tres líneas de trabajo del estudio'],['03','Diseñar','Dirección oscura y sobria, con la foto de obra a página completa'],['04','Entregar','Sitio responsive de diez páginas, con WhatsApp como primer contacto']],
        result: 'Sitio en vivo de diez páginas hecho en Next.js. Seis obras con ficha propia, filtrables por vivienda, comercial e industria: cuatro viviendas —la N|O en Sarmiento, de 2022 y 120 m², con la pileta reflectante que duplica la fachada de hormigón y listones desde la calle; la A|G, con pérgola y madera vertical que unifica el frente; la G|P, con la losa prolongada que forma galería antes de la puerta; y la S|M, que muestra el interiorismo con una escalera suspendida en la doble altura—; la Farmacia Van Strate, 120 m² en Sarmiento, un local de persianas metálicas sin identidad convertido en 2024 en fachada de paneles perforados verde menta con marquesina y espejo de agua; y la Planta Industrial Canavesio, la nave para Canavesio Hnos., fabricante de maquinaria agrícola desde que tres hermanos abrieron un taller metalúrgico en los años cincuenta, con la identidad roja y blanca llevada a toda la fachada y visible desde la ruta. El contacto entra por WhatsApp, sin formulario ni base de datos.',
        learn: 'Cuando un estudio chico hace tres cosas distintas, mostrarlas mezcladas parece falta de foco y separarlas por línea de trabajo lo vuelve un argumento: la planta industrial deja de ser una obra suelta y pasa a ser la prueba de que el equipo aguanta esa escala. El sitio también deja escrito lo que todavía no está confirmado —superficies, años y la dirección exacta del estudio— en vez de completarlo con datos inventados.' },
      en: { cat: 'Web Design + UX/UI', title: 'Van Strate Cortese', role: 'LCS · Web Design & Development', client: 'Arch. Alejandra Van Strate · Arch. Santiago Cortese · Santa Fe, Argentina',
        problem: 'Alejandra Van Strate and Santiago Cortese are two architects who design and run construction out of Santa Fe with no practice structure in between: the same two are in charge from drawing to handover, across housing, retail and industrial work. All of it lived on Instagram — 132 posts and 8,553 followers on @vcestudio.arq — where a whole industrial plant and a finished kitchen compete inside the same square and the work sinks down the feed within a fortnight. They had nowhere to show that the practice does all three, or how each job was resolved.',
        goal: 'Lift the work out of the feed and order it by what the practice actually does — housing, retail and industry — so an industrial client can commission a plant without doubting that the same pair also builds houses.',
        steps: [['01','Discover','What has been built, what opens doors, and what is still unconfirmed'],['02','Define','Six projects filtered by the practice\'s three lines of work'],['03','Design','Dark, sober direction with full-page construction photography'],['04','Deliver','A responsive ten-page site with WhatsApp as the first contact']],
        result: 'A live ten-page site built in Next.js. Six projects with their own page, filtered by housing, retail and industry: four houses — N|O in Sarmiento, 2022 and 120 m², its reflecting pool doubling the concrete-and-batten façade from the street; A|G, with a pergola and vertical timber unifying the front; G|P, where the extended slab forms a covered walk before the door; and S|M, showing the interior work through a suspended staircase in the double-height space —; Farmacia Van Strate, 120 m² in Sarmiento, a shuttered shopfront with no identity turned in 2024 into a mint-green perforated-panel façade with a canopy and a water feature; and the Canavesio Industrial Plant, built for Canavesio Hnos., a farm machinery maker going back to the metalwork shop three brothers opened in the fifties, its red and white brand identity carried across the whole façade and visible from the road. Contact runs through WhatsApp, with no form and no database.',
        learn: 'When a small practice does three different things, showing them jumbled reads as a lack of focus, while separating them by line of work turns it into an argument: the industrial plant stops being a stray project and becomes proof the team can hold that scale. The site also states plainly what is not yet confirmed — areas, years and the studio\'s exact address — instead of filling the gaps with invented data.' }
    }
  };

  const L = {
    es: { role: 'Rol', year: 'Año', client: 'Cliente', tools: 'Herramientas', problem: 'Problema / Desafío', goal: 'Objetivo', process: 'Proceso', result: 'Resultado', learn: 'Aprendizajes clave', stack: 'Stack' },
    en: { role: 'Role', year: 'Year', client: 'Client', tools: 'Tools', problem: 'Problem / Challenge', goal: 'Goal', process: 'Process', result: 'Result', learn: 'Key takeaways', stack: 'Stack' }
  };

  function buildModalShell() {
    if (document.getElementById('modal')) return;
    document.body.insertAdjacentHTML('beforeend', `
      <div class="modal" id="modal" aria-hidden="true" role="dialog" aria-modal="true" aria-label="Case study">
        <div class="modal__scrim"></div>
        <div class="modal__panel">
          <button class="modal__close" aria-label="Cerrar">
            <span data-es="Cerrar" data-en="Close">Cerrar</span>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M18 6 6 18M6 6l12 12"/></svg>
          </button>
          <div class="modal__body"></div>
        </div>
      </div>`);
  }

  window.__lcsProjects = function init(ctx) {
    const { $, $$ } = ctx;
    if (!$('[data-project]')) return; // only on Proyectos page

    buildModalShell();
    const m = $('#modal');
    const panel = $('.modal__body', m);
    let key = null;

    /* Solo abren caso las claves propias del catálogo: un ancla como
       #constructor devolvía algo heredado de Object y rompía el panel. */
    const isCase = k => Object.prototype.hasOwnProperty.call(PROJECTS, k);


    function render(k) {
      const base = isCase(k) ? PROJECTS[k] : null; if (!base) return;
      const lang = window.__lcsLang === 'en' ? 'en' : 'es';
      const p = base[lang] || base.es, T = L[lang] || L.es;
      const hint = lang === 'en' ? '↕ Scroll · click to visit the live site ↗' : '↕ Scrolleá · clic para visitar el sitio real ↗';
      const shots = (base.full || []).map(f =>
        `<img src="assets/${f}" alt="${p.title} — preview" loading="lazy" data-shot>`).join('');
      const preview = `
        <a class="modal-preview" href="https://${base.url}" target="_blank" rel="noopener noreferrer" aria-label="${lang === 'en' ? 'Visit live site' : 'Visitar sitio real'}: ${base.url}">
          <div class="modal-preview__bar">
            <span class="modal-preview__dot modal-preview__dot--red"></span>
            <span class="modal-preview__dot modal-preview__dot--yellow"></span>
            <span class="modal-preview__dot modal-preview__dot--green"></span>
            <span class="modal-preview__url">${base.url}</span>
          </div>
          <div class="modal-preview__screen" data-empty="${lang === 'en' ? 'Screenshot coming soon' : 'Screenshot pendiente'}">${shots}</div>
          <div class="modal-preview__hint">${hint}</div>
        </a>`;
      panel.innerHTML = `
        <div class="cs-inner">
          ${preview}
          <div class="cs-cat">${p.cat}</div>
          <h2 class="cs-title">${p.title}</h2>
          <div class="cs-meta">
            <div class="cs-meta__cell"><div class="k">${T.role}</div><div class="v">${p.role}</div></div>
            <div class="cs-meta__cell"><div class="k">${T.year}</div><div class="v">${base.year}</div></div>
            <div class="cs-meta__cell"><div class="k">${T.client}</div><div class="v">${p.client}</div></div>
            <div class="cs-meta__cell"><div class="k">${T.tools}</div><div class="v">${base.tools.join(' · ')}</div></div>
          </div>
          <div class="cs-body">
            <div>
              <div class="cs-block"><h4>${T.problem}</h4><p>${p.problem}</p></div>
              <div class="cs-block"><h4>${T.goal}</h4><p>${p.goal}</p></div>
            </div>
            <div>
              <div class="cs-block"><h4>${T.result}</h4><p>${p.result}</p></div>
              <div class="cs-block"><h4>${T.learn}</h4><p>${p.learn}</p></div>
            </div>
          </div>
          <div class="cs-block"><h4>${T.process}</h4>
            <div class="cs-steps">${p.steps.map(s => `<div class="cs-step"><b>${s[0]} ${s[1]}</b><span>${s[2]}</span></div>`).join('')}</div>
          </div>
          <div class="cs-block"><h4>${T.stack}</h4>
            <div class="cs-stack">${base.tools.map(t => `<span class="cs-tag">${t}</span>`).join('')}</div>
          </div>
        </div>`;
      /* Una captura que no está todavía no debe dejar un hueco roto:
         se quita cuando el navegador avisa que no pudo cargarla. (Antes
         iba en un atributo onerror, que la política de contenido bloquea.) */
      $$('[data-shot]', panel).forEach(img => {
        img.addEventListener('error', () => img.remove(), { once: true });
      });
    }

    function open(k, pushHash = true) {
      if (!isCase(k)) return;
      key = k; render(k);
      if (pushHash && location.hash !== '#' + k) history.replaceState(null, '', '#' + k);
      m.classList.add('open'); m.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    }
    function close() {
      m.classList.remove('open'); m.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = ''; key = null;
      if (location.hash) history.replaceState(null, '', location.pathname + location.search);
    }

    window.__modalRerender = () => { if (key && m.classList.contains('open')) render(key); };
    $$('[data-project]').forEach(c => c.addEventListener('click', () => open(c.getAttribute('data-project'))));

    /* "Ver todos los proyectos" — despliega los casos que van más allá de los 6
       primeros. Las etiquetas se guardan en data-es/data-en para que el switch
       de idioma las siga traduciendo después de togglear. */
    const moreBtn = $('[data-work-more]');
    const grid = $('#work-grid');
    if (moreBtn && grid) {
      const LABELS = {
        show: { es: 'Ver todos los proyectos', en: 'View all projects' },
        hide: { es: 'Ver menos', en: 'Show less' }
      };
      const label = $('span', moreBtn) || moreBtn;
      moreBtn.addEventListener('click', () => {
        const expanded = grid.classList.toggle('is-expanded');
        const next = expanded ? LABELS.hide : LABELS.show;
        label.setAttribute('data-es', next.es);
        label.setAttribute('data-en', next.en);
        label.textContent = window.__lcsLang === 'en' ? next.en : next.es;
        moreBtn.setAttribute('aria-expanded', String(expanded));
        if (!expanded) {
          // al plegar, volver al arranque de la subseccion ("Todos los proyectos"),
          // descontando el alto del nav fijo para que el titulo no quede tapado
          const head = grid.closest('.shell').querySelector('.kicker-row') || grid;
          const nav = document.getElementById('site-header');
          const offset = (nav ? nav.getBoundingClientRect().height : 0) + 24;
          const top = head.getBoundingClientRect().top + window.pageYOffset - offset;
          const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
          window.scrollTo({ top: Math.max(top, 0), behavior: reduced ? 'auto' : 'smooth' });
        }
        // el grid cambió de alto: ScrollTrigger tiene que recalcular
        if (window.ScrollTrigger) window.ScrollTrigger.refresh();
      });
    }
    /* Deep-link: /proyectos#p8 abre el caso directo (lo usan las tarjetas
       del carrusel del home). Si el caso está entre los plegados, primero
       se despliega el grid para que quede visible al cerrar el modal. */
    function openFromHash() {
      const k = (location.hash || '').slice(1);
      if (!isCase(k)) return;
      const card = $(`[data-project="${k}"]`);
      if (card && card.classList.contains('work__card--more') && grid && !grid.classList.contains('is-expanded')) {
        if (moreBtn) moreBtn.click(); else grid.classList.add('is-expanded');
      }
      open(k, false);
    }
    openFromHash();
    window.addEventListener('hashchange', openFromHash);

    $('.modal__scrim', m).addEventListener('click', close);
    $('.modal__close', m).addEventListener('click', close);
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && m.classList.contains('open')) close(); });
  };
})();
